## When to use

```js
class Timer {
  constructor() { this.ticks = 0; }

  start() {
    // ✅ Arrow preserves 'this' from the class instance
    setInterval(() => { this.ticks++; }, 1000);
  }
}

const nums = [1, 2, 3];
const doubled = nums.map(n => n * 2);       // ✅ short, clear
const odds    = nums.filter(n => n % 2);    // ✅
const total   = nums.reduce((a, n) => a+n); // ✅
```

## When NOT to use

```js
// ❌ Object method — 'this' is the outer scope, not the object
const counter = {
  count: 0,
  increment: () => { this.count++; }, // 'this' is NOT counter
};

// ✅ Use shorthand method syntax instead:
const counter = {
  count: 0,
  increment() { this.count++; },  // 'this' is counter
};

// ❌ Constructor:
const Person = (name) => { this.name = name; };
new Person('Aaron'); // TypeError: Person is not a constructor

// ❌ Generator:
const gen = *() => { yield 1; }; // SyntaxError — use function*

// ❌ When you need 'arguments':
const logArgs = () => console.log(arguments); // ReferenceError
```

detailMdTr:
## Ne zaman kullanılır

```js
class Timer {
  constructor() { this.ticks = 0; }

  start() {
    // ✅ Arrow, class instance'ından 'this'i korur
    setInterval(() => { this.ticks++; }, 1000);
  }
}

const nums = [1, 2, 3];
const doubled = nums.map(n => n * 2);       // ✅ kısa, açık
const odds    = nums.filter(n => n % 2);    // ✅
const total   = nums.reduce((a, n) => a+n); // ✅
```

## Ne zaman KULLANILMAMALI

```js
// ❌ Nesne metodu — 'this' nesne değil dıştaki kapsam
const counter = {
  count: 0,
  increment: () => { this.count++; }, // 'this' counter DEĞİL
};

// ✅ Bunun yerine kısayol metod sözdizimi kullanın:
const counter = {
  count: 0,
  increment() { this.count++; },  // 'this' counter'dır
};

// ❌ Constructor:
const Person = (name) => { this.name = name; };
new Person('Aaron'); // TypeError: Person bir constructor değil

// ❌ Generator:
const gen = *() => { yield 1; }; // SyntaxError — function* kullanın

// ❌ 'arguments' gerektiğinde:
const logArgs = () => console.log(arguments); // ReferenceError
```

