## Object destructuring

```js
const user = { name: 'Aaron', age: 30, role: 'dev' };

// Basic:
const { name, role } = user;

// Rename:
const { name: userName, role: userRole } = user;

// Default value:
const { name, level = 1 } = user; // level is 1 if not in user

// Nested:
const { address: { city } } = { address: { city: 'London' } };

// Function parameter:
function greet({ name, greeting = 'Hi' }) {
  return `${greeting}, ${name}`;
}
greet({ name: 'Aaron' }); // 'Hi, Aaron'
```

## Array destructuring

```js
const [a, b, c] = [1, 2, 3];

// Skip elements:
const [first, , third] = [10, 20, 30]; // third = 30

// Rest:
const [head, ...tail] = [1, 2, 3, 4];  // tail = [2,3,4]

// Swap values:
let x = 1, y = 2;
[x, y] = [y, x]; // x=2, y=1

// From function return:
const [data, error] = await fetchData();
```

## In for...of

```js
const map = new Map([['a', 1], ['b', 2]]);
for (const [key, value] of map) {
  console.log(key, value);
}
```

detailMdTr:
## Nesne destructuring

```js
const user = { name: 'Aaron', age: 30, role: 'dev' };

// Temel:
const { name, role } = user;

// Yeniden adlandırma:
const { name: userName, role: userRole } = user;

// Varsayılan değer:
const { name, level = 1 } = user; // level, user'da yoksa 1'dir

// İç içe:
const { address: { city } } = { address: { city: 'Londra' } };

// Fonksiyon parametresi:
function greet({ name, greeting = 'Merhaba' }) {
  return `${greeting}, ${name}`;
}
greet({ name: 'Aaron' }); // 'Merhaba, Aaron'
```

## Dizi destructuring

```js
const [a, b, c] = [1, 2, 3];

// Elemanları atla:
const [first, , third] = [10, 20, 30]; // third = 30

// Rest:
const [head, ...tail] = [1, 2, 3, 4];  // tail = [2,3,4]

// Değerleri takas et:
let x = 1, y = 2;
[x, y] = [y, x]; // x=2, y=1

// Fonksiyon dönüşünden:
const [data, error] = await fetchData();
```

## for...of içinde

```js
const map = new Map([['a', 1], ['b', 2]]);
for (const [key, value] of map) {
  console.log(key, value);
}
```
